mapper.select:
WITH ranked_runs AS ( SELECT id, space_id, source_document_id, status, error_message, created_at, completed_at, ROW_NUMBER() OVER ( PARTITION BY source_document_id ORDER BY created_at DESC, id DESC ) AS latest_rank, FIRST_VALUE(CASE WHEN status = 'completed' THEN id END) OVER ( PARTITION BY source_document_id ORDER BY CASE WHEN status = 'completed' THEN 0 ELSE 1 END, created_at DESC, id DESC ) AS latest_completed_extraction_id FROM ai_extraction_runs WHERE space_id = #{spaceId} AND source_document_id IN
#{documentId}
) SELECT id, space_id, source_document_id, status, error_message, created_at, completed_at, latest_completed_extraction_id FROM ranked_runs WHERE latest_rank = 1
